using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using TekstilCAD.Patterns;
using FourPieceResearch;
using SyntheticBridge;
using UpperPreview=BodiceWpfReader.Preview;
namespace MeasurementSlice;

internal sealed class ResearchWindow:Window
{
    readonly ComboBox model=new(){ItemsSource=new[]{Contract.Model},SelectedIndex=-1},unit=new(){ItemsSource=new[]{"mm","cm"},SelectedIndex=-1},sample=new(){ItemsSource=new[]{"synthetic-base","synthetic-scaled","synthetic-distinct"},SelectedIndex=-1};
    readonly Dictionary<string,TextBox> fields=new(StringComparer.Ordinal);readonly CheckBox confirmed=new(){Content="Bütün değerlerin seçilen birimdeki uydurma test girdileri olduğunu kontrol ettim; gerçek kişi ölçüsü kullanmıyorum."},symmetry=new(){Content="Alt deneyin sağ/sol simetrisini ve ön/arka eşit etek ucu dağılımını kabul ediyorum."};
    readonly TextBlock status=new(){TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,8)};readonly FourView view=new(){Height=600,Visibility=Visibility.Collapsed};CancellationTokenSource? active;long epoch;
    internal ResearchWindow(){Title="Ölçüden dört parça — yalnız sentetik araştırma";Width=1050;Height=850;var body=new StackPanel{Margin=new Thickness(16)};Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};
        body.Children.Add(new TextBlock{Text="YALNIZ UYDURMA TEST ÖLÇÜLERİ: Gerçek kişi verisi girmeyin. Çalışan motor/bağımlılık kimliği, lisans ve ağ yalıtımı doğrulanmadı. Formdaki değerler worker'a gönderilmez; yalnız sabit test kimliği gönderilir. Üst/alt kaynak ve bolluklar farklıdır, bel bağlantısı ve uyum çözülmedi. CAD, üretim, export, baskı veya cihaz yok. Ölçüm yönergeleri uzman tarafından doğrulanmadı; uzman incelemesi ve numune prova gerekir.",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.DarkRed});
        body.Children.Add(new TextBlock{Text="Deney modeli (zorunlu)",Margin=new Thickness(0,12,0,3)});body.Children.Add(model);body.Children.Add(new TextBlock{Text="Tüm uzunlukların birimi (zorunlu; omuz eğimi derece)",Margin=new Thickness(0,8,0,3)});body.Children.Add(unit);
        body.Children.Add(new TextBlock{Text="İsteğe bağlı: birimi seçtikten sonra sabit uydurma örneği elle doldurmak yerine açıkça yükleyebilirsiniz.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,3)});body.Children.Add(sample);var fill=new Button{Content="Seçili sentetik örnek değerlerini doldur",Margin=new Thickness(0,5,0,8)};body.Children.Add(fill);
        body.Children.Add(new TextBlock{Text="Üst gövde — 15 ölçü; göğüs pensi 06:00, ikinci pens yok, arka bel/omuz pensi yok. Motorun diğer sabit seçenekleri araştırma sözleşmesindedir.",TextWrapping=TextWrapping.Wrap,FontWeight=FontWeights.Bold});
        foreach(var d in BreannaMeasurementGate.Definitions)AddField(body,"upper."+d.Key,d.Label+(d.IsAngle?" (derece)":" (seçilen birimde)"),d.Instructions);
        body.Children.Add(new TextBlock{Text="Alt A-kesim — 11 ayrı yay ve bolluk değeri; üst ile aynı beden veya dikiş ilişkisi varsayılmaz.",TextWrapping=TextWrapping.Wrap,FontWeight=FontWeights.Bold,Margin=new Thickness(0,14,0,0)});
        for(int i=0;i<Contract.LowerKeys.Length;i++)AddField(body,"lower."+Contract.LowerKeys[i],Contract.LowerLabels[i]+" (seçilen birimde)",i<4?"Belirtilen ön veya arka beden yayı; bolluk dahil değil.":i<8?"Bu yay için ayrı, sıfır veya pozitif bolluk.":i==10?"Bitmiş giysi etek çevresi; bolluk dahil.":"Bel hattından belirtilen düzeye uzunluk.");
        body.Children.Add(symmetry);body.Children.Add(confirmed);var run=new Button{Content="Yalnız sentetik gövdeleri ve alt panelleri göster",Margin=new Thickness(0,12,0,0)};body.Children.Add(run);body.Children.Add(status);body.Children.Add(view);
        model.SelectionChanged+=(_,_)=>Invalidate();unit.SelectionChanged+=(_,_)=>Invalidate();sample.SelectionChanged+=(_,_)=>Invalidate();symmetry.Unchecked+=(_,_)=>Invalidate();confirmed.Unchecked+=(_,_)=>Invalidate();
        fill.Click+=(_,_)=>{if(sample.SelectedItem is not string id||unit.SelectedItem is not string u){status.Text="Önce birim ve sentetik örnek seçin.";return;}var values=Contract.SampleInput(id,u);foreach(var (key,value) in values)fields[key].Text=value;status.Text="Sentetik örnek dolduruldu; model, simetri ve ölçüleri ayrıca onaylayın.";};
        run.Click+=async(_,_)=>{long mine=++epoch;active?.Cancel();var cts=new CancellationTokenSource();active=cts;view.Panels=null;view.Visibility=Visibility.Collapsed;status.Text="Sentetik araştırma hesaplanıyor…";try{var values=fields.ToDictionary(x=>x.Key,x=>x.Value.Text,StringComparer.Ordinal);var result=await Slice.Run(model.SelectedItem as string,unit.SelectedItem as string,confirmed.IsChecked==true,symmetry.IsChecked==true,values,(id,ct)=>Worker.Run(Worker.Real,id,TimeSpan.FromSeconds(15),ct),cts.Token);if(mine!=epoch||cts.IsCancellationRequested)return;view.Panels=Layout.Build(result.Upper,result.Lower);view.Visibility=Visibility.Visible;view.InvalidateVisual();status.Text=$"{result.Id}: dört bağımsız sentetik parça; dikiş ve üretim onayı yok.";}catch(OperationCanceledException){}catch{if(mine==epoch)status.Text="Girdi veya sentetik sonuç geçersiz. Yalnız sabit uydurma örnekleri kullanın.";}finally{if(ReferenceEquals(active,cts))active=null;cts.Dispose();}};
        Closed+=(_,_)=>{epoch++;active?.Cancel();};
    }
    void AddField(System.Windows.Controls.Panel body,string key,string label,string help){body.Children.Add(new TextBlock{Text=label+"\n"+help,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,2)});var input=new TextBox();fields.Add(key,input);body.Children.Add(input);input.TextChanged+=(_,_)=>Invalidate();}
    void Invalidate(){epoch++;active?.Cancel();view.Panels=null;view.Visibility=Visibility.Collapsed;view.InvalidateVisual();if(confirmed.IsChecked==true)confirmed.IsChecked=false;status.Text="Girdi değişti; kontrol ve onayı yenileyin.";}
    internal bool StartsEmpty=>model.SelectedIndex==-1&&unit.SelectedIndex==-1&&confirmed.IsChecked!=true&&fields.Count==26&&fields.Values.All(x=>x.Text.Length==0);
    internal void ShowForTest(SliceResult r){view.Panels=Layout.Build(r.Upper,r.Lower);view.Visibility=Visibility.Visible;}
    internal void EditForTest()=>fields["lower.frontWaist"].Text="351";
    internal bool VisibleForTest=>view.Visibility==Visibility.Visible;
    internal void ConfirmForTest()=>confirmed.IsChecked=true;
    internal bool ConfirmedForTest=>confirmed.IsChecked==true;
    internal void SelectSampleForTest()=>sample.SelectedItem="synthetic-scaled";
    internal bool HasBothColorsForTest(){view.Measure(new Size(1000,600));view.Arrange(new Rect(0,0,1000,600));view.UpdateLayout();var bitmap=new RenderTargetBitmap(1000,600,96,96,PixelFormats.Pbgra32);bitmap.Render(view);var data=new byte[1000*600*4];bitmap.CopyPixels(data,4000,0);bool blue=false,orange=false;for(int i=0;i<data.Length;i+=4){if(data[i]>120&&data[i+1]<180&&data[i+2]<110&&data[i]>data[i+1])blue=true;if(data[i]<80&&data[i+1]>60&&data[i+1]<180&&data[i+2]>180)orange=true;}return blue&&orange;}
}
internal static class Program
{
    [STAThread]static int Main(string[] args){if(args.SequenceEqual(new[]{"--verify"})){try{var r=VerifyAsync().GetAwaiter().GetResult();var app=new Application();var w=new ResearchWindow();if(!w.StartsEmpty)throw new Exception("form prefilled");w.ConfirmForTest();w.ShowForTest(r);if(!w.VisibleForTest||!w.HasBothColorsForTest())throw new Exception("preview missing or blank");w.EditForTest();if(w.VisibleForTest||w.ConfirmedForTest)throw new Exception("stale view or confirmation");w.ConfirmForTest();w.ShowForTest(r);w.SelectSampleForTest();if(w.VisibleForTest||w.ConfirmedForTest)throw new Exception("stale sample selection");Console.WriteLine("PASS: 26 explicit fields, cm/mm, synthetic-only gate before worker, two real worker fixtures and stale view; no window shown");return 0;}catch(Exception e){Console.Error.WriteLine("FAIL: "+e.Message);return 1;}}return new Application().Run(new ResearchWindow());}
    static async Task<SliceResult> VerifyAsync(){var first=Contract.SampleInput("synthetic-base","mm");var cm=Contract.SampleInput("synthetic-base","cm");if(Contract.Validate(Contract.Model,"mm",true,true,first).Id!="synthetic-base"||Contract.Validate(Contract.Model,"cm",true,true,cm).Id!="synthetic-base")throw new Exception("unit normalization");int calls=0;async Task<UpperPreview> Run(string id,CancellationToken ct){calls++;return await Worker.Run(Worker.Real,id,TimeSpan.FromSeconds(20),ct);}
        async Task Reject(IReadOnlyDictionary<string,string> f,string? u="mm",bool confirm=true,bool symmetry=true,string? m=Contract.Model){int before=calls;try{await Slice.Run(m,u,confirm,symmetry,f,Run,CancellationToken.None);throw new Exception("invalid data accepted");}catch(InvalidOperationException){}if(calls!=before)throw new Exception("invalid data reached worker");}
        foreach(string key in first.Keys){var missing=new Dictionary<string,string>(first);missing.Remove(key);await Reject(missing);}var wrong=new Dictionary<string,string>(first){["upper.waist"]="741"};await Reject(wrong);var mismatched=new Dictionary<string,string>(first){["lower.backWaist"]="371"};await Reject(mismatched);var extra=new Dictionary<string,string>(first){["extra"]="1"};await Reject(extra);var nonnumeric=new Dictionary<string,string>(first){["upper.biceps"]="NaN"};await Reject(nonnumeric);var tooLong=new Dictionary<string,string>(first){["lower.frontWaist"]=new string('9',25)};await Reject(tooLong);await Reject(first,u:null);await Reject(first,confirm:false);await Reject(first,symmetry:false);await Reject(first,m:null);using(var cancelled=new CancellationTokenSource()){cancelled.Cancel();try{await Slice.Run(Contract.Model,"mm",true,true,first,Run,cancelled.Token);throw new Exception("cancel ignored");}catch(OperationCanceledException){}if(calls!=0)throw new Exception("cancel reached worker");}
        var a=await Slice.Run(Contract.Model,"mm",true,true,first,Run,CancellationToken.None);var b=await Slice.Run(Contract.Model,"mm",true,true,Contract.SampleInput("synthetic-scaled","mm"),Run,CancellationToken.None);if(calls!=2||a.Id!="synthetic-base"||b.Id!="synthetic-scaled"||a.ProductionAllowed||a.ExportAllowed||a.Lower.CanApplyOrExport||a.Upper.Parts[0].Segments[0].To==b.Upper.Parts[0].Segments[0].To||a.Lower.Front[1]==b.Lower.Front[1]||Layout.Build(a.Upper,a.Lower).Length!=4)throw new Exception("synthetic vertical slice");
        using(var lateCancel=new CancellationTokenSource()){var pending=new TaskCompletionSource<UpperPreview>(TaskCreationOptions.RunContinuationsAsynchronously);var late=Slice.Run(Contract.Model,"mm",true,true,first,(_,_)=>pending.Task,lateCancel.Token);lateCancel.Cancel();pending.SetResult(a.Upper);try{await late;throw new Exception("late result accepted");}catch(OperationCanceledException){}}
        return a;}
}
